const data = $input.first().json.json
const chars = data.alignment.characters;
const starts = data.alignment.character_start_times_seconds;
const ends = data.alignment.character_end_times_seconds;

const result = [];

let currentWord = '';
let wordStart = null;

for (let i = 0; i < chars.length; i++) {
  const char = chars[i];

  // Detecta inicio de palabra
  if (currentWord === '' && char !== ' ') {
    wordStart = starts[i];
  }

  // Si el carácter no es espacio, lo agrega a la palabra actual
  if (char !== ' ') {
    currentWord += char;
  }

  // Si es espacio o fin de texto, cierra palabra
  if (char === ' ' || i === chars.length - 1) {
    if (currentWord !== '') {
      result.push({
        word: currentWord,
        start: wordStart,
        end: ends[i - (char === ' ' ? 1 : 0)]
      });
      currentWord = '';
      wordStart = null;
    }
  }
}

return({result})

